);
create index if not exists idx_documents_chapter on public.documents(chapter_id, document_type_code);
create index if not exists idx_documents_type    on public.documents(document_type_code, status);
create index if not exists idx_documents_term    on public.documents(term_code, reporting_year);

-- ---------------------------------------------------------------------------
-- updated_at triggers
-- ---------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

do $$
declare t text;
begin
  foreach t in array array[
    'chapters','profiles','chapter_user_links','reviewer_assignments',
    'reporting_windows','rubric_versions','submissions',
    'submission_item_responses','documents','document_types'
  ] loop
    execute format(
      'drop trigger if exists set_updated_at_%1$s on public.%1$s;
       create trigger set_updated_at_%1$s before update on public.%1$s
       for each row execute procedure public.set_updated_at();', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Auto-create a profile whenever an auth user is created. Role comes from the
-- user's raw metadata (defaults to the shared 'chapter' role).
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_profile()
returns trigger as $$
begin
  insert into public.profiles (id, full_name, email, role_code, district, region)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'full_name', ''),
    new.email,
    coalesce(new.raw_user_meta_data ->> 'role_code', 'chapter'),
    new.raw_user_meta_data ->> 'district',
    new.raw_user_meta_data ->> 'region'
  )
  on conflict (id) do nothing;
  return new;
end;
$$ language plpgsql security definer;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_profile();


-- ===========================================================================
-- Row Level Security
-- Access is enforced in the database, not just the UI. At 800+ chapters this
-- is also the isolation boundary between districts/regions: a reviewer or
-- chapter must never be able to read another scope's rows.
--
-- Role helpers are SECURITY DEFINER and STABLE so policies don't recurse
-- through profiles (each chapter/reviewer check would otherwise re-select
-- profiles and re-trigger its own policy).
-- ===========================================================================

create or replace function public.current_role()
returns text language sql stable security definer set search_path = public as $$
  select role_code from public.profiles where id = auth.uid();
$$;

create or replace function public.current_district()
returns text language sql stable security definer set search_path = public as $$
  select district from public.profiles where id = auth.uid();
$$;

create or replace function public.current_region()
returns text language sql stable security definer set search_path = public as $$
  select region from public.profiles where id = auth.uid();
$$;

-- The chapter(s) a shared login is linked to.
create or replace function public.current_chapter_ids()
returns setof uuid language sql stable security definer set search_path = public as $$
  select chapter_id from public.chapter_user_links
   where profile_id = auth.uid() and is_active = true;
$$;

create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.current_role() = 'admin', false);
$$;

create or replace function public.is_executive()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.current_role() = 'executive_director', false);
$$;

-- ---------------------------------------------------------------------------
-- Referential / read-mostly tables: any authenticated user may read; only
-- admins may write. (Small lookup tables.)
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'chapter_types','chapter_statuses','app_roles','report_terms',
    'regions','districts','rubric_versions','rubric_sections',
    'rubric_subsections','rubric_items','document_types'
  ] loop
    execute format('alter table public.%1$s enable row level security;', t);
    execute format('drop policy if exists %1$s_read on public.%1$s;', t);
    execute format($f$
      create policy %1$s_read on public.%1$s for select
      to authenticated using (true);
    $f$, t);
    execute format('drop policy if exists %1$s_admin_write on public.%1$s;', t);
    execute format($f$
      create policy %1$s_admin_write on public.%1$s for all
      to authenticated using (public.is_admin()) with check (public.is_admin());
    $f$, t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- chapters: everyone signed in can read the roster (needed for queues and
-- imports); only admins write.
-- ---------------------------------------------------------------------------
alter table public.chapters enable row level security;

drop policy if exists chapters_read on public.chapters;
create policy chapters_read on public.chapters
  for select to authenticated using (true);

drop policy if exists chapters_admin_write on public.chapters;
create policy chapters_admin_write on public.chapters
  for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- profiles: you see yourself, plus admins/exec see everyone. Reviewers need
-- to see their counterpart's name, so district/regional scopes can read
-- profiles of peers in their own scope — kept narrow to avoid a roster leak.
-- ---------------------------------------------------------------------------
alter table public.profiles enable row level security;

drop policy if exists profiles_self_read on public.profiles;
create policy profiles_self_read on public.profiles
  for select to authenticated
  using (
    id = auth.uid()
    or public.is_admin()
    or public.is_executive()
    or (public.current_role() = 'district_director' and district = public.current_district())
    or (public.current_role() = 'rvp' and region = public.current_region())
  );

drop policy if exists profiles_self_update on public.profiles;
create policy profiles_self_update on public.profiles
  for update to authenticated
  using (id = auth.uid() or public.is_admin())
  with check (id = auth.uid() or public.is_admin());

drop policy if exists profiles_admin_insert on public.profiles;
create policy profiles_admin_insert on public.profiles
  for insert to authenticated with check (public.is_admin() or id = auth.uid());

-- ---------------------------------------------------------------------------
-- chapter_user_links / reviewer_assignments: admin-managed; a chapter may read
-- its own link; a reviewer may read rows assigned to them.
-- ---------------------------------------------------------------------------
alter table public.chapter_user_links enable row level security;
drop policy if exists cul_read on public.chapter_user_links;
create policy cul_read on public.chapter_user_links
  for select to authenticated
  using (
    profile_id = auth.uid()
    or chapter_id in (select public.current_chapter_ids())
    or public.is_admin()
  );
drop policy if exists cul_admin_write on public.chapter_user_links;
create policy cul_admin_write on public.chapter_user_links
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

alter table public.reviewer_assignments enable row level security;
drop policy if exists ra_read on public.reviewer_assignments;
create policy ra_read on public.reviewer_assignments
  for select to authenticated
  using (
    public.is_admin()
    or district_director_profile_id = auth.uid()
    or regional_vice_president_profile_id = auth.uid()
  );
drop policy if exists ra_admin_write on public.reviewer_assignments;
create policy ra_admin_write on public.reviewer_assignments
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- reporting_windows: readable by all; admin-managed.
-- ---------------------------------------------------------------------------
alter table public.reporting_windows enable row level security;
drop policy if exists rw_read on public.reporting_windows;
create policy rw_read on public.reporting_windows for select to authenticated using (true);
drop policy if exists rw_admin_write on public.reporting_windows;
create policy rw_admin_write on public.reporting_windows
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- submissions: the core scoping rule.
--   chapter     -> only its own chapter's submissions
--   DD          -> submissions for chapters in their district
--   RVP         -> submissions for chapters in their region
--   exec/admin  -> all
-- Writes: a chapter may create/update its OWN draft/returned submission only.
-- Reviewers never write the row itself; they write approval_actions.
-- ---------------------------------------------------------------------------
alter table public.submissions enable row level security;

drop policy if exists submissions_read on public.submissions;
create policy submissions_read on public.submissions
  for select to authenticated
  using (
    public.is_admin()
    or public.is_executive()
    or chapter_id in (select public.current_chapter_ids())
    or (public.current_role() = 'district_director'
        and chapter_id in (select id from public.chapters where district = public.current_district()))
    or (public.current_role() = 'rvp'
        and chapter_id in (select id from public.chapters where region = public.current_region()))
  );

drop policy if exists submissions_chapter_insert on public.submissions;
create policy submissions_chapter_insert on public.submissions
  for insert to authenticated
  with check (
    chapter_id in (select public.current_chapter_ids())
    and workflow_status in ('draft','returned')
  );

drop policy if exists submissions_chapter_update on public.submissions;
create policy submissions_chapter_update on public.submissions
  for update to authenticated
  using (
    chapter_id in (select public.current_chapter_ids())
    and workflow_status in ('draft','returned')
  )
  with check (
    chapter_id in (select public.current_chapter_ids())
    and workflow_status in ('draft','returned','submitted')
  );

-- Admin/exec may move a submission through review states (approve/return/reopen).
drop policy if exists submissions_reviewer_update on public.submissions;
create policy submissions_reviewer_update on public.submissions
  for update to authenticated
  using (
    public.is_admin()
    or public.is_executive()
    or (public.current_role() = 'district_director'
        and chapter_id in (select id from public.chapters where district = public.current_district()))
    or (public.current_role() = 'rvp'
        and chapter_id in (select id from public.chapters where region = public.current_region()))
  )
  with check (true);

-- ---------------------------------------------------------------------------
-- submission_item_responses: readable/writable only in the parent
-- submission's scope; chapters only while the submission is editable.
-- ---------------------------------------------------------------------------
alter table public.submission_item_responses enable row level security;

drop policy if exists responses_read on public.submission_item_responses;
create policy responses_read on public.submission_item_responses
  for select to authenticated
  using (
    submission_id in (
      select id from public.submissions
    )
  );

drop policy if exists responses_chapter_write on public.submission_item_responses;
create policy responses_chapter_write on public.submission_item_responses
  for all to authenticated
  using (
    submission_id in (
      select id from public.submissions
       where chapter_id in (select public.current_chapter_ids())
         and workflow_status in ('draft','returned')
    )
  )
  with check (
    submission_id in (
      select id from public.submissions
       where chapter_id in (select public.current_chapter_ids())
         and workflow_status in ('draft','returned')
    )
  );

-- ---------------------------------------------------------------------------
-- approval_actions: readable in scope; insert only by the reviewer who owns
-- that lane (or admin/exec for reopen).
-- ---------------------------------------------------------------------------
alter table public.approval_actions enable row level security;

drop policy if exists approvals_read on public.approval_actions;
create policy approvals_read on public.approval_actions
  for select to authenticated
  using (submission_id in (select id from public.submissions));

drop policy if exists approvals_insert on public.approval_actions;
create policy approvals_insert on public.approval_actions
  for insert to authenticated
  with check (
    reviewer_profile_id = auth.uid()
    and submission_id in (select id from public.submissions)
  );

-- ---------------------------------------------------------------------------
-- audit_log: append-only; readable by admin/exec, insert by anyone acting.
-- ---------------------------------------------------------------------------
alter table public.audit_log enable row level security;
drop policy if exists audit_read on public.audit_log;
create policy audit_read on public.audit_log
  for select to authenticated
  using (public.is_admin() or public.is_executive());
drop policy if exists audit_insert on public.audit_log;
create policy audit_insert on public.audit_log
  for insert to authenticated
  with check (actor_profile_id = auth.uid() or public.is_admin());

-- ---------------------------------------------------------------------------
-- documents: a chapter sees its own uploads; reviewers see uploads for
-- chapters in their scope; admin sees all. Uploads by admin or the owning
-- chapter. document_types governs the allowed formats.
-- ---------------------------------------------------------------------------
alter table public.documents enable row level security;

drop policy if exists documents_read on public.documents;
create policy documents_read on public.documents
  for select to authenticated
  using (
    public.is_admin()
    or public.is_executive()
    or chapter_id in (select public.current_chapter_ids())
    or (public.current_role() = 'district_director'
        and chapter_id in (select id from public.chapters where district = public.current_district()))
    or (public.current_role() = 'rvp'
        and chapter_id in (select id from public.chapters where region = public.current_region()))
  );

drop policy if exists documents_insert on public.documents;
create policy documents_insert on public.documents
  for insert to authenticated
  with check (
    public.is_admin()
    or chapter_id in (select public.current_chapter_ids())
  );

drop policy if exists documents_update on public.documents;
create policy documents_update on public.documents
  for update to authenticated
  using (
    public.is_admin()
    or chapter_id in (select public.current_chapter_ids())
  )
  with check (true);

drop policy if exists documents_admin_delete on public.documents;
create policy documents_admin_delete on public.documents
  for delete to authenticated using (public.is_admin());


-- ===========================================================================
-- Reporting views for the district / regional / national rollups.
--
-- All views are security_invoker = on so they run with the *querying* role's
-- privileges: a district director querying a rollup only aggregates rows RLS
-- already lets them see. Without this, the view would evaluate as its owner
-- and leak every scope.
--
-- The rollups are built LEFT JOIN from the active chapter roster (cross
-- joined against every term/year that has ever been reported or opened), NOT
-- inner-joined from submissions — a chapter that hasn't started still has to
-- count in the denominator, or completion % is meaningless (3 finalized out
-- of the only 3 touched would read as 100% while 800 sit at zero).
-- ===========================================================================

-- Distinct term/year pairs for dashboard filters.
create or replace view public.v_reporting_terms
  with (security_invoker = on) as
select term_code, reporting_year from public.submissions where reporting_year is not null
union
select term_code, reporting_year from public.reporting_windows where reporting_year is not null;

-- Per-submission rollup row (one chapter / term / year).
create or replace view public.v_submission_rollup
  with (security_invoker = on) as
select
  c.id            as chapter_id,
  c.chapter_key,
  c.chapter_name,
  c.chapter_type_code,
  c.district,
  c.region,
  c.status_code,
  s.id            as submission_id,
  s.term_code,
  s.reporting_year,
  s.workflow_status,
  s.district_review_status,
  s.regional_review_status,
  s.executive_review_status,
  s.final_score,
  s.max_score,
  case when s.max_score > 0
       then round((s.final_score::numeric / s.max_score::numeric) * 100, 2)
       else 0 end as pct_score
from public.submissions s
join public.chapters c on c.id = s.chapter_id;

-- Active-chapter roster x every reported/opened term — the denominator spine.
create or replace view public.v_roster_spine
  with (security_invoker = on) as
select
  c.id as chapter_id, c.chapter_key, c.chapter_name, c.chapter_type_code,
  c.district, c.region,
  p.term_code, p.reporting_year
from public.chapters c
cross join (
  select term_code, reporting_year from public.v_reporting_terms where reporting_year is not null
) p
where c.status_code = 'Active';

drop view if exists public.v_district_rollup;
create view public.v_district_rollup
  with (security_invoker = on) as
select
  sp.district,
  sp.term_code,
  sp.reporting_year,
  count(*)                                              as chapters_total,
  count(s.id)                                           as chapters_started,
  count(*) filter (where s.workflow_status = 'finalized') as chapters_finalized,
  count(*) filter (where s.district_review_status = 'approved') as district_approved,
  coalesce(sum(s.final_score), 0)                       as points_earned,
  coalesce(sum(s.max_score), 0)                         as points_possible,
  case when coalesce(sum(s.max_score), 0) > 0
       then round((sum(s.final_score)::numeric / sum(s.max_score)::numeric) * 100, 2)
       else 0 end                                       as avg_score_pct,
  case when count(*) > 0
       then round((count(s.id)::numeric / count(*)::numeric) * 100, 2)
       else 0 end                                       as completion_rate_pct
from public.v_roster_spine sp
left join public.submissions s
  on s.chapter_id = sp.chapter_id
 and s.term_code = sp.term_code
 and s.reporting_year = sp.reporting_year
group by sp.district, sp.term_code, sp.reporting_year;

drop view if exists public.v_region_rollup;
create view public.v_region_rollup
  with (security_invoker = on) as
select
  sp.region,
  sp.term_code,
  sp.reporting_year,
  count(*)                                              as chapters_total,
  count(s.id)                                           as chapters_started,
  count(*) filter (where s.workflow_status = 'finalized') as chapters_finalized,
  count(*) filter (where s.regional_review_status = 'approved') as region_approved,
  count(distinct sp.district)                           as districts_total,
  coalesce(sum(s.final_score), 0)                       as points_earned,
  coalesce(sum(s.max_score), 0)                         as points_possible,
  case when coalesce(sum(s.max_score), 0) > 0
       then round((sum(s.final_score)::numeric / sum(s.max_score)::numeric) * 100, 2)
       else 0 end                                       as avg_score_pct,
  case when count(*) > 0
       then round((count(s.id)::numeric / count(*)::numeric) * 100, 2)
       else 0 end                                       as completion_rate_pct
from public.v_roster_spine sp
left join public.submissions s
  on s.chapter_id = sp.chapter_id
 and s.term_code = sp.term_code
 and s.reporting_year = sp.reporting_year
group by sp.region, sp.term_code, sp.reporting_year;

drop view if exists public.v_national_rollup;
create view public.v_national_rollup
  with (security_invoker = on) as
select
  sp.term_code,
  sp.reporting_year,
  count(*)                                              as chapters_total,
  count(s.id)                                           as chapters_started,
  count(*) filter (where s.workflow_status = 'finalized') as chapters_finalized,
  count(*) filter (where s.workflow_status = 'pending_executive') as pending_executive,
  count(distinct sp.region)                             as regions_total,
  count(distinct sp.district)                           as districts_total,
  coalesce(sum(s.final_score), 0)                       as points_earned,
  coalesce(sum(s.max_score), 0)                         as points_possible,
  case when coalesce(sum(s.max_score), 0) > 0
       then round((sum(s.final_score)::numeric / sum(s.max_score)::numeric) * 100, 2)
       else 0 end                                       as avg_score_pct,
  case when count(*) > 0
       then round((count(s.id)::numeric / count(*)::numeric) * 100, 2)
       else 0 end                                       as completion_rate_pct
from public.v_roster_spine sp
left join public.submissions s
  on s.chapter_id = sp.chapter_id
 and s.term_code = sp.term_code
 and s.reporting_year = sp.reporting_year
group by sp.term_code, sp.reporting_year;


-- ===========================================================================
-- CONVERGENCE: bring an older scaffold up to the current app schema.
-- Safe to run repeatedly; only adds what is missing, never drops or overwrites.
-- ===========================================================================

-- ternary scoring column for the "mandatory item" rule (ships with default 0,
-- so a future -1 rollout needs no migration)
alter table public.rubric_items
  add column if not exists mandatory_penalty integer not null default 0;

-- ternary answer column (yes | no | na)
alter table public.submission_item_responses
  add column if not exists answer_code text;

do $$
begin
  -- if a legacy boolean column exists, fold it into answer_code
  if exists (select 1 from information_schema.columns
             where table_schema = 'public'
               and table_name = 'submission_item_responses'
               and column_name = 'answer_yes') then
    execute $sql$
      update public.submission_item_responses
         set answer_code = case when answer_yes then 'yes' else 'no' end
       where answer_code is null
    $sql$;
  end if;
  update public.submission_item_responses set answer_code = 'no' where answer_code is null;
end $$;

alter table public.submission_item_responses alter column answer_code set not null;

do $$
begin
  if not exists (select 1 from pg_constraint
                 where conrelid = 'public.submission_item_responses'::regclass
                   and conname = 'submission_item_responses_answer_code_check') then
    alter table public.submission_item_responses
      add constraint submission_item_responses_answer_code_check
      check (answer_code in ('yes','no','na'));
  end if;
end $$;

-- ===========================================================================
-- UNIQUE-KEY GUARDS
-- The app upserts on these keys. On a project that already had an older
-- scaffold, the matching constraint may exist under a different name (or not
-- at all). A uniquely-named unique index enforces the same rule and lets the
-- upsert "on conflict (<cols>)" clauses work either way. No-op when present.
-- ===========================================================================
create unique index if not exists uq_chapters_chapter_key          on public.chapters(chapter_key);
create unique index if not exists uq_submissions_chapter_term_year  on public.submissions(chapter_id, term_code, reporting_year);
create unique index if not exists uq_responses_submission_item      on public.submission_item_responses(submission_id, rubric_item_id);
create unique index if not exists uq_chapter_user_links             on public.chapter_user_links(chapter_id, profile_id);
create unique index if not exists uq_rubric_versions_code           on public.rubric_versions(version_code);
create unique index if not exists uq_rubric_sections                on public.rubric_sections(rubric_version_id, section_code);
create unique index if not exists uq_rubric_subsections             on public.rubric_subsections(rubric_section_id, subsection_code);
create unique index if not exists uq_reporting_windows_code         on public.reporting_windows(window_code);


