  chapter_type_code = excluded.chapter_type_code,
  university = excluded.university,
  district = excluded.district,
  region = excluded.region,
  status_code = excluded.status_code,
  is_dechartered = excluded.is_dechartered;

-- --------------------- reporting window (default) ------------------------
-- Opens a Fall window for 2026 and marks it active ONLY if no active window
-- already exists, so re-running never disturbs a window you opened yourself.
insert into public.reporting_windows
  (window_code, term_code, reporting_year, opens_on, closes_on, is_active)
select
  'fall-2026', 'fall', 2026, '2026-08-01', '2026-11-30',
  not exists (select 1 from public.reporting_windows where is_active = true)
on conflict (window_code) do nothing;

-- --------------------- document framework (tax + special event) ---------
insert into public.document_types (
  code, label, category, description, allowed_extensions,
  max_size_mb, applies_to_types, is_active, display_order
) values
  ('annual_irs_990', 'IRS Form 990 (or 990-EZ / 990-N)', 'tax', 'Annual information return filed with the IRS by chapters with a foundation or 501(c)(3) status. Upload the accepted filing.', array['pdf'], 25, array[]::text[], true, 10),
  ('chapter_audit', 'Chapter Financial Audit', 'tax', 'Most recent chapter audit. Per Chapman criteria 1.6, the audit may not be older than 120 days past the end of the fraternal year.', array['pdf'], 25, array[]::text[], true, 20),
  ('chapter_tax_return', 'Chapter Tax Return / Filing Confirmation', 'tax', 'Filed chapter tax return or the e-file acceptance confirmation.', array['pdf'], 25, array[]::text[], true, 30),
  ('foundation_990', 'Chapter Foundation 501(c)(3) Filing', 'tax', 'Separate 990 series filing for a chapter-affiliated foundation, where one exists.', array['pdf'], 25, array[]::text[], true, 40),
  ('grip_submission', 'GRIP Submission', 'other', 'General Records & Information Platform (GRIP) submission evidence.', array['pdf'], 25, array['xlsx'], false, 0),
  ('special_event_checklist', 'Special Event Checklist', 'special_event', 'Completed special event planning and compliance checklist (format TBD — framework placeholder).', array['pdf'], 25, array['xlsx'], false, 25),
  ('special_event_after_action', 'Special Event After-Action Report', 'special_event', 'Post-event report submitted after a special event (format TBD — framework placeholder).', array['pdf'], 25, array['25'], false, 0)
on conflict (code) do update set
